/* @lc app=leetcode id=3953 lang=kotlin */ class Solution { fun maxScore(nums: IntArray, maxVal: Int): Int = maxOf(400, nums.max(), maxVal).let { mx -> IntArray(mx + 1).also { f -> nums.forEach { f[it]++ } }.let { f -> IntArray(mx + 1).also { mc -> (1..mx).forEach { d -> (d..mx step d).forEach { mc[d] += f[it] } } }.let { mc -> BooleanArray(mx + 1) { it >= 2 }.also { s -> (2..316).forEach { i -> if (s[i]) (i * i..mx step i).forEach { s[it] = false } } }.let { pr -> IntArray(mx + 1) { 1 }.also { mu -> (2..mx).filter { pr[it] }.forEach { p -> (p..mx step p).forEach { mu[it] = -mu[it] }.let { if (p.toLong() * p <= mx) (p * p..mx step p * p).forEach { mu[it] = 0 } } } }.let { mu -> IntArray(mx + 1).also { cop -> (1..mx).filter { mu[it] != 0 }.forEach { d -> (d..mx step d).forEach { cop[it] += mu[d] * mc[d] } } }.let { cop -> (1..mx).filter { it <= maxVal || f[it] > 0 }.maxOf { v -> (nums.size - cop[v]).let { c -> v - (if (f[v] > 0) (if (v > 1) c - 1 else 0) else if (c >= 1) c else 1) } } } } } } } } }